CREATE TABLE recurring_schedules(id TEXT PRIMARY KEY, payload TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, active INTEGER NOT NULL DEFAULT 1, next_index INTEGER NOT NULL DEFAULT 0);
CREATE TABLE bill_occurrences(id TEXT PRIMARY KEY, schedule_id TEXT NOT NULL REFERENCES recurring_schedules(id), due_date TEXT NOT NULL, wallet_id TEXT NOT NULL REFERENCES wallets(id), amount TEXT NOT NULL, name TEXT NOT NULL, note TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'due' CHECK(status IN ('due','paid','skipped')), transaction_id TEXT UNIQUE REFERENCES transactions(id), UNIQUE(schedule_id,due_date));
